	SaveNpc();
	SaveObj();
	LoadMap("临安城.map");
	LoadNpc("Linan.npc");
	LoadObj("Linan.obj");
	SetPlayerPos(153,309);
	SetPlayerDir(3);
	If ($FromFengChi == 0) @Lable0;
	If ($FromFengChi == 4) @Lable4;
	If ($FromFengChi == 7) @Lable7;
	If ($FromFengChi == 8) @Lable8;
	If ($FromFengChi == 9) @Lable10;
	If ($FromFengChi == 14) @Label9;
