	SetPlayerState(0);
	Assign($FromFengChi,5);
	SetNpcPos("婕儿",138,79);
	DelNpc("燕若雪");
	DelNpc("柴嵩");
	SetMapTrap(4,"trap4.txt");
	SetMapTrap(5,"trap5.txt");
	SaveMapTrap();
	Assign($LinAnJieEr,3);
	FadeIn();
	ShowMessage("临安");
	Return;

